import java.io.*;
import java.net.*;
import java.sql.*;
import java.util.concurrent.*;
import javax.servlet.*;
import javax.servlet.http.*;

public class ReportServlet extends HttpServlet {
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");
    private final ExecutorService pool = Executors.newFixedThreadPool(4);

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportId = req.getParameter("id");
        String format = req.getParameter("format");
        String callback = req.getParameter("callback");

        if (reportId == null || reportId.isEmpty()) {
            resp.sendError(400, "Missing report id");
            return;
        }

        // Validate format parameter
        if (format != null && !format.matches("^(json|xml|csv)$")) {
            resp.sendError(400, "Invalid format");
            return;
        }

        try {
            String result = fetchReport(reportId, format);

            if (callback != null && !callback.isEmpty()) {
                // JSONP support for legacy dashboard widgets
                resp.setContentType("application/javascript");
                resp.getWriter().write(callback + "(" + result + ");");
            } else {
                resp.setContentType("application/json");
                resp.getWriter().write(result);
            }
        } catch (SQLException e) {
            resp.sendError(500, "Database error");
        }
    }

    private String fetchReport(String reportId, String format) throws SQLException {
        // Using parameterized query - safe from SQLi
        String sql = "SELECT id, title, content, created_at FROM reports WHERE id = ?";

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement stmt = conn.prepareStatement(sql)) {
            stmt.setString(1, reportId);
            ResultSet rs = stmt.executeQuery();

            if (rs.next()) {
                StringBuilder json = new StringBuilder();
                json.append("{\"id\":\"").append(escapeJson(rs.getString("id")))
                    .append("\",\"title\":\"").append(escapeJson(rs.getString("title")))
                    .append("\",\"content\":\"").append(escapeJson(rs.getString("content")))
                    .append("\",\"created\":\"").append(escapeJson(rs.getString("created_at")))
                    .append("\"}");
                return json.toString();
            }
            return "{\"error\":\"not found\"}";
        }
    }

    private String escapeJson(String input) {
        if (input == null) return "";
        return input.replace("\\", "\\\\")
                    .replace("\"", "\\\"")
                    .replace("\n", "\\n")
                    .replace("\r", "\\r")
                    .replace("\t", "\\t");
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // Async report generation with user-supplied template path
        String templateName = req.getParameter("template");
        if (templateName == null) {
            resp.sendError(400);
            return;
        }

        // Normalize path separators and check for traversal
        String normalized = templateName.replace('\\', '/');
        if (normalized.contains("..") || normalized.startsWith("/")) {
            resp.sendError(403, "Invalid template path");
            return;
        }

        String basePath = getServletContext().getRealPath("/WEB-INF/templates/");
        File templateFile = new File(basePath, normalized);

        // Verify canonical path is under base
        if (!templateFile.getCanonicalPath().startsWith(
                new File(basePath).getCanonicalPath())) {
            resp.sendError(403, "Path traversal detected");
            return;
        }

        if (!templateFile.exists()) {
            resp.sendError(404, "Template not found");
            return;
        }

        resp.setStatus(202);
        resp.getWriter().write("{\"status\":\"queued\"}");
    }
}
